@GetMapping("/reports")
Report list(@AuthenticationPrincipal WorkloadPrincipal who) {   // typed descriptor
    if (who == null) throw new AccessDeniedException("anonymous");
    return reports.forTenant(who.tenantId(), who.roles());
}
