@Inject SecurityContext securityContext;

public Report report() {
    Principal caller = securityContext.getCallerPrincipal();   // null if unauthenticated
    if (caller == null) throw new NotAuthorizedException("login");
    if (!securityContext.isCallerInRole("reports.reader")) throw new ForbiddenException();
    return reports.forCaller(caller.getName());
}
